"""Exact connectome state-count and slot-count table."""
from __future__ import annotations
import math


def synapse_slots(n: int) -> int:
    """Potential undirected synapses among n neurons: C(n, 2)."""
    return n * (n - 1) // 2


def state_count_digits(n: int) -> int:
    """Number of decimal digits of the state count 2 ** C(n,2)."""
    return int(synapse_slots(n) * math.log10(2.0)) + 1


def report(neuron_counts: list[int]) -> None:
    for n in neuron_counts:
        s = synapse_slots(n)
        print(f"N={n:>6}  slots={s:>12}  states=2^{s}  (~{state_count_digits(n)} digits)")


if __name__ == "__main__":
    report([2, 5, 10, 100, 1000, 10 ** 6])

"""Bekenstein energy-radius lower bounds for storing an N-neuron mind."""
from __future__ import annotations
import math

HBAR = 1.054_571_817e-34
C = 2.997_924_58e8
LN2 = math.log(2.0)
PI = math.pi


def synapse_slots(n: int) -> int:
    return n * (n - 1) // 2


def energy_radius_bound(n: int) -> float:
    """Lower bound on R*E (J*m) to store an n-neuron connectome."""
    return HBAR * C * LN2 / (2.0 * PI) * synapse_slots(n)


def energy_radius_quadratic(n: int) -> float:
    """Quadratic-form lower bound (n >= 1)."""
    return HBAR * C * LN2 / (4.0 * PI) * (n - 1) ** 2


if __name__ == "__main__":
    for n in (1000, 10 ** 6, 86_000_000_000):
        print(f"N={n:>14}  R*E >= {energy_radius_bound(n):.3e} J*m  "
              f"(quadratic: {energy_radius_quadratic(n):.3e})")

