function SYNAPSE_SLOTS(N):
    require N >= 0
    return N * (N - 1) / 2   # integer division; exact since N(N-1) is even

function MIN_DESCRIPTION_BITS(N):
    return C(N, 2)
function IS_COMPRESSIBLE_BELOW(N, M):
    return M >= 2 ** C(N, 2)   # lossless coding needs at least 2^slots codewords

function BEKENSTEIN_CAPACITY_BITS(R, E):
    return 2*pi*R*E / (hbar*c*ln2)
function REQUIRED_ENERGY_RADIUS(N):
    return hbar*c*ln2/(2*pi) * C(N, 2)
function FEASIBLE(N, R, E):
    return C(N, 2) <= BEKENSTEIN_CAPACITY_BITS(R, E)

