from __future__ import annotations
import math

HBAR = 1.054_571_817e-34
C = 2.997_924_58e8
LN2 = math.log(2.0)
PI = math.pi


def bekenstein_capacity_bits(radius: float, energy: float) -> float:
    """Maximum information (bits) storable in a region of given radius/energy."""
    return 2.0 * PI * radius * energy / (HBAR * C * LN2)


def required_energy_radius_product(n: int) -> float:
    """Minimum R*E (J*m) to store an n-neuron mind, via the Bekenstein bound."""
    slots = n * (n - 1) // 2
    return HBAR * C * LN2 / (2.0 * PI) * slots


def feasible(n: int, radius: float, energy: float) -> bool:
    """True iff a region of given radius/energy can store an n-neuron mind."""
    return (n * (n - 1) // 2) <= bekenstein_capacity_bits(radius, energy)
